import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.D2veAa-g.js";const m=JSON.parse('{"title":"软件可靠性基本概念","description":"","frontmatter":{"title":"软件可靠性基本概念"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/软件可靠性基础知识（第二版）/软件可靠性基本概念.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/软件可靠性基础知识（第二版）/软件可靠性基本概念.md","lastUpdated":null}'),r={name:"架构师 在线刷题/51CT0题库 章节练习/软件可靠性基础知识（第二版）/软件可靠性基本概念.md"};function i(n,l,c,e,u,g){return a(),s("div",null,[...l[0]||(l[0]=[o('<h1 id="软件可靠性基本概念" tabindex="-1">软件可靠性基本概念 <a class="header-anchor" href="#软件可靠性基本概念" aria-label="Permalink to &quot;软件可靠性基本概念&quot;">​</a></h1><blockquote><p>共 18 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-【51cto学堂-学员回忆版】系统-16-是指在规定的时间内和规定条件下能有效地实现规定功能的能力。它不仅取决于规定的使用条件等因素-还与设计技术有关。常用的度量指标主要有故障率-或失效率-、平均失效等待时间、平均失效间隔时间和可靠度等。其中-17-是系统在规定工作时间内无故障的概率。" tabindex="-1">Q1. 【51CTO学堂-学员回忆版】系统(16)是指在规定的时间内和规定条件下能有效地实现规定功能的能力。它不仅取决于规定的使用条件等因素，还与设计技术有关。常用的度量指标主要有故障率(或失效率)、平均失效等待时间、平均失效间隔时间和可靠度等。其中，(17)是系统在规定工作时间内无故障的概率。 <a class="header-anchor" href="#q1-【51cto学堂-学员回忆版】系统-16-是指在规定的时间内和规定条件下能有效地实现规定功能的能力。它不仅取决于规定的使用条件等因素-还与设计技术有关。常用的度量指标主要有故障率-或失效率-、平均失效等待时间、平均失效间隔时间和可靠度等。其中-17-是系统在规定工作时间内无故障的概率。" aria-label="Permalink to &quot;Q1. 【51CTO学堂-学员回忆版】系统(16)是指在规定的时间内和规定条件下能有效地实现规定功能的能力。它不仅取决于规定的使用条件等因素，还与设计技术有关。常用的度量指标主要有故障率(或失效率)、平均失效等待时间、平均失效间隔时间和可靠度等。其中，(17)是系统在规定工作时间内无故障的概率。&quot;">​</a></h2><ul><li><strong>A.</strong> 可靠性</li><li><strong>B.</strong> 可用性</li><li><strong>C.</strong> 可理解性</li><li><strong>D.</strong> 可测试性</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q2-【51cto学堂-学员回忆版】系统-16-是指在规定的时间内和规定条件下能有效地实现规定功能的能力。它不仅取决于规定的使用条件等因素-还与设计技术有关。常用的度量指标主要有故障率-或失效率-、平均失效等待时间、平均失效间隔时间和可靠度等。其中-17-是系统在规定工作时间内无故障的概率。" tabindex="-1">Q2. 【51CTO学堂-学员回忆版】系统(16)是指在规定的时间内和规定条件下能有效地实现规定功能的能力。它不仅取决于规定的使用条件等因素，还与设计技术有关。常用的度量指标主要有故障率(或失效率)、平均失效等待时间、平均失效间隔时间和可靠度等。其中，(17)是系统在规定工作时间内无故障的概率。 <a class="header-anchor" href="#q2-【51cto学堂-学员回忆版】系统-16-是指在规定的时间内和规定条件下能有效地实现规定功能的能力。它不仅取决于规定的使用条件等因素-还与设计技术有关。常用的度量指标主要有故障率-或失效率-、平均失效等待时间、平均失效间隔时间和可靠度等。其中-17-是系统在规定工作时间内无故障的概率。" aria-label="Permalink to &quot;Q2. 【51CTO学堂-学员回忆版】系统(16)是指在规定的时间内和规定条件下能有效地实现规定功能的能力。它不仅取决于规定的使用条件等因素，还与设计技术有关。常用的度量指标主要有故障率(或失效率)、平均失效等待时间、平均失效间隔时间和可靠度等。其中，(17)是系统在规定工作时间内无故障的概率。&quot;">​</a></h2><ul><li><strong>A.</strong> 失效率</li><li><strong>B.</strong> 平均失效等待时间</li><li><strong>C.</strong> 平均失效间隔时间</li><li><strong>D.</strong> 可靠度</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q3-在进行架构评估时-首先要明确具体的质量目标-并以之作为判定该架构优劣的标准。为得出这些目标而采用的机制叫做场景-场景是从-63-的角度对与系统的交互的简短措述。" tabindex="-1">Q3. 在进行架构评估时，首先要明确具体的质量目标，并以之作为判定该架构优劣的标准。为得出这些目标而采用的机制叫做场景，场景是从（63）的角度对与系统的交互的简短措述。 <a class="header-anchor" href="#q3-在进行架构评估时-首先要明确具体的质量目标-并以之作为判定该架构优劣的标准。为得出这些目标而采用的机制叫做场景-场景是从-63-的角度对与系统的交互的简短措述。" aria-label="Permalink to &quot;Q3. 在进行架构评估时，首先要明确具体的质量目标，并以之作为判定该架构优劣的标准。为得出这些目标而采用的机制叫做场景，场景是从（63）的角度对与系统的交互的简短措述。&quot;">​</a></h2><ul><li><strong>A.</strong> 用户</li><li><strong>B.</strong> 系统架构师</li><li><strong>C.</strong> 项目管理者</li><li><strong>D.</strong> 风险承担者</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q4-在系统性能评价中通常用平均无故障时间-mtbf-和平均故障修复时间-mttr-分别表示计算机系统的可靠性和可用性-以下关于mtbf和mttr的说法中-错误的是-59-。" tabindex="-1">Q4. 在系统性能评价中通常用平均无故障时间（MTBF）和平均故障修复时间（MTTR）分别表示计算机系统的可靠性和可用性，以下关于MTBF和MTTR的说法中，错误的是（59）。 <a class="header-anchor" href="#q4-在系统性能评价中通常用平均无故障时间-mtbf-和平均故障修复时间-mttr-分别表示计算机系统的可靠性和可用性-以下关于mtbf和mttr的说法中-错误的是-59-。" aria-label="Permalink to &quot;Q4. 在系统性能评价中通常用平均无故障时间（MTBF）和平均故障修复时间（MTTR）分别表示计算机系统的可靠性和可用性，以下关于MTBF和MTTR的说法中，错误的是（59）。&quot;">​</a></h2><ul><li><strong>A.</strong> 平均无故障时间，也就是平均运行多久不出故障，这个时间越大，可用性越好</li><li><strong>B.</strong> 平均故障修复时间，也就是每次故障需要多长时间恢复为正常状态，这个时间越小越好</li><li><strong>C.</strong> 如果两次故障的间隔时间长，而每次故障的修复时间短，则系统的可靠性高</li><li><strong>D.</strong> MTBF小，MTTR大表示系统具有高可靠性和高可用性</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q5-在软件可靠性度量中-mtbf-平均故障间隔时间-的正确定义是-。" tabindex="-1">Q5. 在软件可靠性度量中，MTBF（平均故障间隔时间）的正确定义是（）。 <a class="header-anchor" href="#q5-在软件可靠性度量中-mtbf-平均故障间隔时间-的正确定义是-。" aria-label="Permalink to &quot;Q5. 在软件可靠性度量中，MTBF（平均故障间隔时间）的正确定义是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 从软件运行开始到第一次失效的平均时间</li><li><strong>B.</strong> 软件系统从故障发生到修复完成的平均时间</li><li><strong>C.</strong> 相邻两次故障之间的平均时间，也称为平均故障间隔</li><li><strong>D.</strong> 软件系统在规定时间内不发生失效的概率</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q6-在软件可靠性的定量描述中-关于规定时间的概念-以下描述正确的是-。" tabindex="-1">Q6. 在软件可靠性的定量描述中，关于<code>规定时间</code>的概念，以下描述正确的是（）。 <a class="header-anchor" href="#q6-在软件可靠性的定量描述中-关于规定时间的概念-以下描述正确的是-。" aria-label="Permalink to &quot;Q6. 在软件可靠性的定量描述中，关于`规定时间`的概念，以下描述正确的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 执行时间是指软件从启动开始到运行结束的时间段</li><li><strong>B.</strong> 运行时间是指CPU执行程序指令所用的时间总和</li><li><strong>C.</strong> 自然时间是指日历时间，包括年、月、周、日等自然流逝的时间段</li><li><strong>D.</strong> 三种时间概念在软件可靠性测试中具有相同的作用和意义</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q7-关于软件与硬件在可靠性方面的差异-以下说法正确的是-。" tabindex="-1">Q7. 关于软件与硬件在可靠性方面的差异，以下说法正确的是（）。 <a class="header-anchor" href="#q7-关于软件与硬件在可靠性方面的差异-以下说法正确的是-。" aria-label="Permalink to &quot;Q7. 关于软件与硬件在可靠性方面的差异，以下说法正确的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 软件存在物理退化现象，硬件不存在物理退化</li><li><strong>B.</strong> 软件失效主要由设计错误导致，硬件失效主要由物理退化导致</li><li><strong>C.</strong> 软件复制会改变软件本身的可靠性特征</li><li><strong>D.</strong> 软件版本更新周期通常比硬件更新周期慢</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q8-软件可靠性是指软件产品在规定的条件下和规定的时间区间完成规定功能的能力。关于软件可靠性的特点-下列说法正确的是-。" tabindex="-1">Q8. 软件可靠性是指软件产品在规定的条件下和规定的时间区间完成规定功能的能力。关于软件可靠性的特点，下列说法正确的是（）。 <a class="header-anchor" href="#q8-软件可靠性是指软件产品在规定的条件下和规定的时间区间完成规定功能的能力。关于软件可靠性的特点-下列说法正确的是-。" aria-label="Permalink to &quot;Q8. 软件可靠性是指软件产品在规定的条件下和规定的时间区间完成规定功能的能力。关于软件可靠性的特点，下列说法正确的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 软件存在物理退化现象，这是导致软件失效的主要原因</li><li><strong>B.</strong> 软件内部逻辑高度复杂，设计错误是导致软件失效的主要原因</li><li><strong>C.</strong> 软件的更新周期通常比硬件更慢</li><li><strong>D.</strong> 任何两个软件都不可能绝对相同</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q9-在架构演化评估中-关于可靠性质量属性的度量结果-以下描述正确的是-。" tabindex="-1">Q9. 在架构演化评估中，关于可靠性质量属性的度量结果，以下描述正确的是（）。 <a class="header-anchor" href="#q9-在架构演化评估中-关于可靠性质量属性的度量结果-以下描述正确的是-。" aria-label="Permalink to &quot;Q9. 在架构演化评估中，关于可靠性质量属性的度量结果，以下描述正确的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 可靠性的度量结果是一个实数值</li><li><strong>B.</strong> 可靠性的度量结果包含多个子度量指标</li><li><strong>C.</strong> 可靠性的度量结果是一个布尔值</li><li><strong>D.</strong> 可靠性的度量结果是一个字符串类型</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q10-在软件工程中-广义的软件可靠性测试包括多个环节。以下哪项不属于广义软件可靠性测试的组成部分-。" tabindex="-1">Q10. 在软件工程中，广义的软件可靠性测试包括多个环节。以下哪项不属于广义软件可靠性测试的组成部分（ ）。 <a class="header-anchor" href="#q10-在软件工程中-广义的软件可靠性测试包括多个环节。以下哪项不属于广义软件可靠性测试的组成部分-。" aria-label="Permalink to &quot;Q10. 在软件工程中，广义的软件可靠性测试包括多个环节。以下哪项不属于广义软件可靠性测试的组成部分（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 建模</li><li><strong>B.</strong> 统计</li><li><strong>C.</strong> 调试</li><li><strong>D.</strong> 评价</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q11-在软件可靠性测试中-以下哪项最准确地描述了狭义的软件可靠性测试的特点-。" tabindex="-1">Q11. 在软件可靠性测试中，以下哪项最准确地描述了狭义的软件可靠性测试的特点（ ）。 <a class="header-anchor" href="#q11-在软件可靠性测试中-以下哪项最准确地描述了狭义的软件可靠性测试的特点-。" aria-label="Permalink to &quot;Q11. 在软件可靠性测试中，以下哪项最准确地描述了狭义的软件可靠性测试的特点（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 主要目的是发现软件系统在各个阶段的缺陷</li><li><strong>B.</strong> 在任意环境下进行，以评估软件的整体性能</li><li><strong>C.</strong> 按预先确定的测试用例在预期使用环境中进行，目的是获取可靠性数据</li><li><strong>D.</strong> 主要用于确认软件是否达到可靠性的定性要求</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q12-某软件系统的平均失效前时间-mttf-为100小时-平均恢复前时间-mttr-为5小时-则该系统的平均故障间隔时间-mtbf-为多少小时-。" tabindex="-1">Q12. 某软件系统的平均失效前时间(MTTF)为100小时，平均恢复前时间(MTTR)为5小时，则该系统的平均故障间隔时间(MTBF)为多少小时（ ）。 <a class="header-anchor" href="#q12-某软件系统的平均失效前时间-mttf-为100小时-平均恢复前时间-mttr-为5小时-则该系统的平均故障间隔时间-mtbf-为多少小时-。" aria-label="Permalink to &quot;Q12. 某软件系统的平均失效前时间(MTTF)为100小时，平均恢复前时间(MTTR)为5小时，则该系统的平均故障间隔时间(MTBF)为多少小时（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 100小时</li><li><strong>B.</strong> 105小时</li><li><strong>C.</strong> 95小时</li><li><strong>D.</strong> 110小时</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q13-在软件可靠性分析中-某系统的失效概率f-t-为0-2-运行时间t为100小时。该系统在100小时内的可靠度r-t-最接近以下哪个值-。" tabindex="-1">Q13. 在软件可靠性分析中，某系统的失效概率F(t)为0.2，运行时间t为100小时。该系统在100小时内的可靠度R(t)最接近以下哪个值（ ）。 <a class="header-anchor" href="#q13-在软件可靠性分析中-某系统的失效概率f-t-为0-2-运行时间t为100小时。该系统在100小时内的可靠度r-t-最接近以下哪个值-。" aria-label="Permalink to &quot;Q13. 在软件可靠性分析中，某系统的失效概率F(t)为0.2，运行时间t为100小时。该系统在100小时内的可靠度R(t)最接近以下哪个值（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 0.2</li><li><strong>B.</strong> 0.5</li><li><strong>C.</strong> 0.8</li><li><strong>D.</strong> 1.0</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q14-在软件可靠性的时间概念中-以下哪一种时间指的是软件从启动开始到运行结束的时间段-。" tabindex="-1">Q14. 在软件可靠性的时间概念中，以下哪一种时间指的是软件从启动开始到运行结束的时间段（ ）。 <a class="header-anchor" href="#q14-在软件可靠性的时间概念中-以下哪一种时间指的是软件从启动开始到运行结束的时间段-。" aria-label="Permalink to &quot;Q14. 在软件可靠性的时间概念中，以下哪一种时间指的是软件从启动开始到运行结束的时间段（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 自然时间</li><li><strong>B.</strong> 运行时间</li><li><strong>C.</strong> 执行时间</li><li><strong>D.</strong> 日历时间</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q15-软件可靠性是指软件产品在什么条件下完成规定功能的能力-。" tabindex="-1">Q15. 软件可靠性是指软件产品在什么条件下完成规定功能的能力（ ）。 <a class="header-anchor" href="#q15-软件可靠性是指软件产品在什么条件下完成规定功能的能力-。" aria-label="Permalink to &quot;Q15. 软件可靠性是指软件产品在什么条件下完成规定功能的能力（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 任何条件下和任何时间</li><li><strong>B.</strong> 规定的条件下和规定的时间区间</li><li><strong>C.</strong> 极端条件下和长时间运行</li><li><strong>D.</strong> 用户自定义的条件和时间</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q16-在软件系统可靠性评估中-以下哪个指标表示系统从故障状态恢复到正常工作状态所需的平均时间-。" tabindex="-1">Q16. 在软件系统可靠性评估中，以下哪个指标表示系统从故障状态恢复到正常工作状态所需的平均时间（ ）。 <a class="header-anchor" href="#q16-在软件系统可靠性评估中-以下哪个指标表示系统从故障状态恢复到正常工作状态所需的平均时间-。" aria-label="Permalink to &quot;Q16. 在软件系统可靠性评估中，以下哪个指标表示系统从故障状态恢复到正常工作状态所需的平均时间（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 平均失效间隔时间（MTBF）</li><li><strong>B.</strong> 平均失效等待时间（MTTF）</li><li><strong>C.</strong> 平均故障修复时间（MTTR）</li><li><strong>D.</strong> 平均无故障时间（MTTF）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q17-下列关于可靠性测试的说法错误的是-。" tabindex="-1">Q17. 下列关于可靠性测试的说法错误的是（ ）。 <a class="header-anchor" href="#q17-下列关于可靠性测试的说法错误的是-。" aria-label="Permalink to &quot;Q17. 下列关于可靠性测试的说法错误的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 定义系统剖面是广义可靠性测试的重要手段</li><li><strong>B.</strong> 可以通过可靠性测试发现系统薄弱点</li><li><strong>C.</strong> 广义可靠性测试仅关注系统无故障运行时间</li><li><strong>D.</strong> 狭义可靠性测试通过获取数据评估系统可靠性指标</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q18-阅读以下关于嵌入式系统可靠性设计方面的描述-回答下列问题。【说明】某宇航公司长期从事宇航装备的研制工作-嵌入式系统的可靠性分析与设计已成为该公司产品研制中的核心工作-随着宇航装备的综合化技术发展-嵌入式软件规模发生了巨大变化-代码规模已从原来的几十万扩展到上百万-从而带来了由于软件失效而引起系统可靠性降低的隐患。公司领导非常重视软件可靠性工作-决定抽调王工程师等5人组建可靠性研究团队-专门研究提高本公司宇航装备的系统可靠性和软件可靠性问题-并要求在三个月内-给出本公司在系统和软件设计方面如何考虑可靠性设计的方法和规范。可靠性研究团队很快拿出了系统及硬件的可靠性提高方案-但对于软件可靠性问题始终没有研究出一种普遍认同的方法。【问题1】请用200字以内文字说明系统可靠性的定义及包含的4个子特性-并简要指出提高系统可靠性一般采用哪些技术-【问题2】王工带领的可靠性研究团队之所以没能快速取得软件可靠性问题的技术突破-其核心原因是他们没有搞懂高可靠性软件应具备的特点。软件可靠性一般致力于系统性地减少和消除对软件程序性能有不利影响的系统故障。除非被修改-否则软件系统不会随着时间的推移而发生退化。请根据你对软件可靠性的理解-给出下表所列出的硬件可靠性特征与其对应的软件可靠性特征之间的差异或相似之处-将答案写在答题纸上。【问题3】王工带领的可靠性研究团队在分析了大量相关资料基础上-提出软件的质量和可靠性必须在开发过程构建到软件中-也就是说-为了提高软件的可靠性-必须在需求分析、设计阶段开展软件可靠性筹划和设计。研究团队针对本公司承担的飞行控制系统制定出了一套飞控软件的可靠性设计要求。飞行控制系统是一种双余度同构型系统-输入采用了独立的两路数据通道-在系统内完成输入数据的交叉对比、表决、制导率计算-输出数据的交叉对比、表决、输出等功能-系统的监控模块实现对系统失效或失步的检测与定位。其软件的可靠性设计包括恢复块方法和n版本程序设计方法。请根据恢复块方法工作原理完成下图-在-1-4-中填入恰当的内容。并比较恢复块方法与n版本程序设计方法-将比较结果-5-8-填入下表中。" tabindex="-1">Q18. 阅读以下关于嵌入式系统可靠性设计方面的描述，回答下列问题。【说明】某宇航公司长期从事宇航装备的研制工作，嵌入式系统的可靠性分析与设计已成为该公司产品研制中的核心工作，随着宇航装备的综合化技术发展，嵌入式软件规模发生了巨大变化，代码规模已从原来的几十万扩展到上百万，从而带来了由于软件失效而引起系统可靠性降低的隐患。公司领导非常重视软件可靠性工作，决定抽调王工程师等5人组建可靠性研究团队，专门研究提高本公司宇航装备的系统可靠性和软件可靠性问题，并要求在三个月内，给出本公司在系统和软件设计方面如何考虑可靠性设计的方法和规范。可靠性研究团队很快拿出了系统及硬件的可靠性提高方案，但对于软件可靠性问题始终没有研究出一种普遍认同的方法。【问题1】请用200字以内文字说明系统可靠性的定义及包含的4个子特性，并简要指出提高系统可靠性一般采用哪些技术?【问题2】王工带领的可靠性研究团队之所以没能快速取得软件可靠性问题的技术突破，其核心原因是他们没有搞懂高可靠性软件应具备的特点。软件可靠性一般致力于系统性地减少和消除对软件程序性能有不利影响的系统故障。除非被修改，否则软件系统不会随着时间的推移而发生退化。请根据你对软件可靠性的理解，给出下表所列出的硬件可靠性特征与其对应的软件可靠性特征之间的差异或相似之处，将答案写在答题纸上。【问题3】王工带领的可靠性研究团队在分析了大量相关资料基础上，提出软件的质量和可靠性必须在开发过程构建到软件中，也就是说，为了提高软件的可靠性，必须在需求分析、设计阶段开展软件可靠性筹划和设计。研究团队针对本公司承担的飞行控制系统制定出了一套飞控软件的可靠性设计要求。飞行控制系统是一种双余度同构型系统，输入采用了独立的两路数据通道，在系统内完成输入数据的交叉对比、表决、制导率计算，输出数据的交叉对比、表决、输出等功能，系统的监控模块实现对系统失效或失步的检测与定位。其软件的可靠性设计包括恢复块方法和N版本程序设计方法。请根据恢复块方法工作原理完成下图，在(1)～(4)中填入恰当的内容。并比较恢复块方法与N版本程序设计方法，将比较结果(5)～(8)填入下表中。 <a class="header-anchor" href="#q18-阅读以下关于嵌入式系统可靠性设计方面的描述-回答下列问题。【说明】某宇航公司长期从事宇航装备的研制工作-嵌入式系统的可靠性分析与设计已成为该公司产品研制中的核心工作-随着宇航装备的综合化技术发展-嵌入式软件规模发生了巨大变化-代码规模已从原来的几十万扩展到上百万-从而带来了由于软件失效而引起系统可靠性降低的隐患。公司领导非常重视软件可靠性工作-决定抽调王工程师等5人组建可靠性研究团队-专门研究提高本公司宇航装备的系统可靠性和软件可靠性问题-并要求在三个月内-给出本公司在系统和软件设计方面如何考虑可靠性设计的方法和规范。可靠性研究团队很快拿出了系统及硬件的可靠性提高方案-但对于软件可靠性问题始终没有研究出一种普遍认同的方法。【问题1】请用200字以内文字说明系统可靠性的定义及包含的4个子特性-并简要指出提高系统可靠性一般采用哪些技术-【问题2】王工带领的可靠性研究团队之所以没能快速取得软件可靠性问题的技术突破-其核心原因是他们没有搞懂高可靠性软件应具备的特点。软件可靠性一般致力于系统性地减少和消除对软件程序性能有不利影响的系统故障。除非被修改-否则软件系统不会随着时间的推移而发生退化。请根据你对软件可靠性的理解-给出下表所列出的硬件可靠性特征与其对应的软件可靠性特征之间的差异或相似之处-将答案写在答题纸上。【问题3】王工带领的可靠性研究团队在分析了大量相关资料基础上-提出软件的质量和可靠性必须在开发过程构建到软件中-也就是说-为了提高软件的可靠性-必须在需求分析、设计阶段开展软件可靠性筹划和设计。研究团队针对本公司承担的飞行控制系统制定出了一套飞控软件的可靠性设计要求。飞行控制系统是一种双余度同构型系统-输入采用了独立的两路数据通道-在系统内完成输入数据的交叉对比、表决、制导率计算-输出数据的交叉对比、表决、输出等功能-系统的监控模块实现对系统失效或失步的检测与定位。其软件的可靠性设计包括恢复块方法和n版本程序设计方法。请根据恢复块方法工作原理完成下图-在-1-4-中填入恰当的内容。并比较恢复块方法与n版本程序设计方法-将比较结果-5-8-填入下表中。" aria-label="Permalink to &quot;Q18. 阅读以下关于嵌入式系统可靠性设计方面的描述，回答下列问题。【说明】某宇航公司长期从事宇航装备的研制工作，嵌入式系统的可靠性分析与设计已成为该公司产品研制中的核心工作，随着宇航装备的综合化技术发展，嵌入式软件规模发生了巨大变化，代码规模已从原来的几十万扩展到上百万，从而带来了由于软件失效而引起系统可靠性降低的隐患。公司领导非常重视软件可靠性工作，决定抽调王工程师等5人组建可靠性研究团队，专门研究提高本公司宇航装备的系统可靠性和软件可靠性问题，并要求在三个月内，给出本公司在系统和软件设计方面如何考虑可靠性设计的方法和规范。可靠性研究团队很快拿出了系统及硬件的可靠性提高方案，但对于软件可靠性问题始终没有研究出一种普遍认同的方法。【问题1】请用200字以内文字说明系统可靠性的定义及包含的4个子特性，并简要指出提高系统可靠性一般采用哪些技术?【问题2】王工带领的可靠性研究团队之所以没能快速取得软件可靠性问题的技术突破，其核心原因是他们没有搞懂高可靠性软件应具备的特点。软件可靠性一般致力于系统性地减少和消除对软件程序性能有不利影响的系统故障。除非被修改，否则软件系统不会随着时间的推移而发生退化。请根据你对软件可靠性的理解，给出下表所列出的硬件可靠性特征与其对应的软件可靠性特征之间的差异或相似之处，将答案写在答题纸上。【问题3】王工带领的可靠性研究团队在分析了大量相关资料基础上，提出软件的质量和可靠性必须在开发过程构建到软件中，也就是说，为了提高软件的可靠性，必须在需求分析、设计阶段开展软件可靠性筹划和设计。研究团队针对本公司承担的飞行控制系统制定出了一套飞控软件的可靠性设计要求。飞行控制系统是一种双余度同构型系统，输入采用了独立的两路数据通道，在系统内完成输入数据的交叉对比、表决、制导率计算，输出数据的交叉对比、表决、输出等功能，系统的监控模块实现对系统失效或失步的检测与定位。其软件的可靠性设计包括恢复块方法和N版本程序设计方法。请根据恢复块方法工作原理完成下图，在(1)～(4)中填入恰当的内容。并比较恢复块方法与N版本程序设计方法，将比较结果(5)～(8)填入下表中。&quot;">​</a></h2><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong><p>答案：<br>问题1：<br>系统可靠性定义：系统在规定的时间内及规定的环境条件下，完成规定功能的能力，就是系统无故障运行的概率。    <br>根据国家标准《软件工程产品质量 第1部分：质量模型》(GB/T 16260.1—2006)的规定，系统可靠性包括：成熟性、容错性、易恢复性和可靠性的依从性4个子特性。   <br> 提高系统可靠性一般采用以下4类技术：    (1)冗余技术；    (2)软件容错技术；    (3)双机容错技术；    (4)集群技术。<br>问题2：<br>(1)从硬件角度分析，由于硬件一旦生产完成，其可靠性指标将会随着使用时间延长而逐步老化，从而带来可靠性降低，即呈现失效率服从浴缸曲线；而软件不存在随时间延长而老化的现象，因此，在不考虑软件演化的情况下，失效率在统计上是非增的。    <br>(2)由于硬件是由多种电子器件组成，即使不使用，材料劣化也会导致失效；而软件就不同了，软件一旦调试完成，固化到设备中，在不考虑存储介质的老化因素的前提下，即使不使用该软件，软件也永远不会发生失效。   <br> (3)由于硬件存在可更换性，其硬件通过维修，可恢复原始状态；而对于软件而言，一旦需要维护，必然是存在需求更改、程序存在bug等现象，其维护必然会创建新的软件代码。   <br> (4)一般而言，硬件失效存在一个发展过程，在发生故障之前必然会有报警现象出现，而软件失效之前很少会有警告。<br>问题3：<br>1．恢复块方法：    (1)主块    (2)验证测试    (3)输出正确结果    (4)异常处理    <br>2．恢复块方法与N版本程序设计的比较    (5)表决    (6)反向恢复    (7)差    (8)好</p></strong></p></div></details>',55)])])}const h=t(r,[["render",i]]);export{m as __pageData,h as default};
